INSERT INTO questions (source, year, subject, topic, enunciado, opcoes, gabarito, explicacao) VALUES
  ('exam', 2018, 'Língua Portuguesa', NULL, 'Q1 Item 1 (TPS 2018): Texto I | A pena de morte é uma flagrante violação dos direitos humanos e é incompatível com os princípios do tratamento humanitário e do devido processo legal. Ouve-se, por vezes, o', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Língua Portuguesa', NULL, 'Q1 Item 2 (TPS 2018): Texto I | argumento de que a pena capital tem efeito dissuasório sobre o crime. No entanto, não há comprovação de que exista relação de causalidade entre a pena de morte e o controle efetivo da 7 criminalidade, nem de que ela seja mais eficaz na redução do crime que a pena de reclusão. A própria Assembleia-Geral reconheceu que não existe prova conclusiva do valor 10 dissuasório da pena de morte. Condenar alguém à pena de morte nega o direito à vida, consagrado na Declaração Universal dos Direitos Humanos. 13 A execução é o castigo máximo e irrevogável, e o risco de executar uma pessoa inocente não pode ser ignorado. Trata-se de sanção discriminatória, já que as pessoas pobres, 16 as pertencentes a minorias raciais, étnicas ou religiosas específicas têm maior probabilidade de ser condenadas à morte. ', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Língua Portuguesa', NULL, 'Q2 Item 1 (TPS 2018): Texto II | O Brasil se absteve na votação do projeto de resolução sobre “a deterioração grave e contínua dos direitos humanos e da situação humanitária na República Árabe da', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Língua Portuguesa', NULL, 'Q2 Item 2 (TPS 2018): Texto II | Síria”. Estamos plenamente conscientes da grave situação dos direitos humanos na região, que precisa ser devidamente analisada por este conselho. Apesar das últimas modificações 7 no texto, a resolução ainda não reconhece a responsabilidade e não repudia devidamente a participação de vários grupos armados da oposição (…) por graves violações dos direitos 10 humanos e do direito humanitário. Essa lacuna pode erroneamente transmitir uma mensagem de tolerância a essas graves irregularidades e, assim, incentivar ainda mais violência 13 contra a população civil. É também lamentável a falta de ênfase na necessidade de maior envolvimento de todas as partes nas negociações políticas. Não há solução militar para 16 a crise e a insistência em ver uma vitória militar como a única saída é uma causa re', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Língua Portuguesa', NULL, 'Q2 Item 3 (TPS 2018): Texto II | O Brasil votou a favor do projeto de resolução sobre a situação dos direitos humanos na Síria adotado hoje, 2 de julho, pelo Conselho de Direitos Humanos das Nações Unidas', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Língua Portuguesa', NULL, 'Q2 Item 4 (TPS 2018): Texto II | (CDH). O texto adotado, fruto de um minucioso e construtivo esforço negociador que contou com a ativa participação brasileira, buscou aproximar posições e levar em conta 7 preocupações de países que, como o Brasil, tinham problemas de fundo com o texto anterior. O resultado apresenta maior equilíbrio em comparação à resolução adotada na última sessão 10 do CDH, em março último, o que permitiu o voto brasileiro favorável. No texto, estão contempladas a necessidade de buscar uma solução política para o conflito e a 13 responsabilidade de todas as partes pelo respeito aos direitos humanos. (…) O Brasil saudou o reconhecimento da necessidade de uma solução política negociada para o conflito, 16 bem como a responsabilidade primária das autoridades sírias pela garantia dos direitos humanos do po', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Direito Internacional Público', NULL, 'Q3 Item 1 (TPS 2018): Texto IV | Nossos blocos econômicos concordaram em inaugurar nova etapa negociadora do acordo comercial. O acordo deverá incluir compromissos ambiciosos de redução', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Direito Internacional Público', NULL, 'Q3 Item 2 (TPS 2018): Texto IV | tarifária e medidas de superação dos entraves não tarifários e outras distorções ou barreiras ao comércio. As regras de origem dos produtos devem ser 7 estabelecidas de forma clara e simples, e os mecanismos de certificação e verificação devem permitir o funcionamento transparente de administração das regras de origem, sem dar 10 margem a decisões discricionárias que venham a criar obstáculos desnecessários ao comércio. Na esfera de investimentos, o acordo deverá 13 estabelecer um ambiente conducente ao fortalecimento dos fluxos entre ambos os blocos econômicos. Para tanto, deverão ser buscadas medidas contra expropriação arbitrária, com base 16em regras precisas e estáveis do Estado de direito. Texto V', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Direito Internacional Público', NULL, 'Q3 Item 3 (TPS 2018): Texto IV | A conclusão exitosa das negociações do acordo comercial entre nossos blocos econômicos é uma das prioridades da política externa. O potencial de exportação e de 4 investimentos será consideravelmente incrementado por meio do melhor acesso a mercados e da progressiva liberalização do comércio. 7 Em que pesem as novas oportunidades, Vossa Excelência deverá propor que o acordo preveja mecanismos de salvaguarda a serem aplicados na hipótese de aumento brusco 10 e excessivo de importações que possam causar sério dano à estrutura produtiva de uma das partes. A delegação do outro bloco regional poderá propor 13 que as negociações comerciais levem em consideração repercussões em matéria de meio ambiente, responsabilidade social e questões trabalhistas, com medidas de proteção 16 àqueles setores e ', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Direito Internacional Público', NULL, 'Q3 Item 4 (TPS 2018): Texto IV | A segunda ignorância que tira o merecimento ao amor é não conhecer quem ama, a quem ama. Quantas cousas há no mundo muito amadas, que, se as conhecera quem as ama,', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Direito Internacional Público', NULL, 'Q4 Item 1 (TPS 2018): Com base nas ideias desenvolvidas nos textos VI, VII, VIII e IX, julgue (C ou E) os itens que se seguem. | Infere-se do texto VI que, para Padre Antonio Vieira, a ignorância que tira o merecimento ao amor é não conhecer o que se ama nem ter com o que se ama o adequado cuidado.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Direito Internacional Público', NULL, 'Q4 Item 2 (TPS 2018): Com base nas ideias desenvolvidas nos textos VI, VII, VIII e IX, julgue (C ou E) os itens que se seguem. | No texto VII, não obstante o emprego dos substantivos “imprevidência, irresponsabilidade, instabilidade, vagabundagem” (R. 12 e 13), Sérgio Buarque de Holanda não atribui conotação negativa à ética da aventura.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Direito Internacional Público', NULL, 'Q4 Item 3 (TPS 2018): Com base nas ideias desenvolvidas nos textos VI, VII, VIII e IX, julgue (C ou E) os itens que se seguem. | Com base nas ideias expressas no texto VIII, é correto concluir que, na opinião de Gilberto Freyre, uma organização baseada em um sistema de regiões poderia substituir o sistema de Estados federados e fortalecer a união nacional, embora a proposta de “regionalismo” contenha o risco do separatismo lamentavelmente desenvolvido pela República por meio do que ele chama de “estadualismo” (R.7).', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Direito Internacional Público', NULL, 'Q5 Item 1 (TPS 2018): Com relação aos aspectos linguísticos do texto VII, julgue (C ou E) os itens seguintes. | Infere-se do texto que o homem aventureiro é um tipo belicoso, contrário “à estabilidade, à paz, à segurança pessoal” (R. 17 e 18), e materialista, pois concentra esforços no “rápido proveito material” (R. 18 e 19).', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Direito Internacional Público', NULL, 'Q5 Item 2 (TPS 2018): Com relação aos aspectos linguísticos do texto VII, julgue (C ou E) os itens seguintes. | Na variedade culta da língua portuguesa falada ou escrita no Brasil, além da ocorrência de expressões como “podem assinalar-se” (R.1), em que o pronome aparece em ênclise à forma verbal infinitiva, verifica-se a ocorrência de próclise a essa forma verbal — podem se assinalar —, ambas consideradas corretas pela gramática.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Direito Internacional Público', NULL, 'Q5 Item 4 (TPS 2018): Com relação aos aspectos linguísticos do texto VII, julgue (C ou E) os itens seguintes. | O trecho “tanto uma oposição absoluta como uma incompreensão radical” (R.22) exprime uma relação de proporcionalidade entre “uma oposição absoluta” e “uma incompreensão radical”. CESPE | CEBRASPE – IRBr – Aplicação: 2018', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Língua Portuguesa', NULL, 'Q6 Item 1 (TPS 2018): A respeito dos aspectos linguísticos do texto IX, julgue (C ou E) os itens que se seguem. | As formas verbais “tivessem amortecido” (R. 6 e 7) e “absorvesse” (R.8) remetem, respectivamente, às fases final e inicial dos eventos que exprimem.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Língua Portuguesa', NULL, 'Q6 Item 2 (TPS 2018): A respeito dos aspectos linguísticos do texto IX, julgue (C ou E) os itens que se seguem. | A expressão “porventura” indica que o trecho “por uma noção mais nítida, porventura, das limitações humanas e terrenas” (R. 14 e 15) tem sentido hipotético.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Língua Portuguesa', NULL, 'Q6 Item 3 (TPS 2018): A respeito dos aspectos linguísticos do texto IX, julgue (C ou E) os itens que se seguem. | Nas linhas 9 e 10, “é que” caracteriza-se como expressão expletiva, empregada para realçar o conteúdo “não os inquietam, aqui, os extraordinários portentos, nem a esperança deles” (R. 10 e 11).', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Língua Portuguesa', NULL, 'Q6 Item 4 (TPS 2018): A respeito dos aspectos linguísticos do texto IX, julgue (C ou E) os itens que se seguem. | O advérbio “melhor” (R.19) foi empregado pelo autor para retificar conteúdo já enunciado.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Língua Portuguesa', NULL, 'Q7 Item 1 (TPS 2018): Texto X | A facilidade de comunicações acabou com esses tanques em que floresciam as diferentes culturas. Quando antes se olhava o mapa-múndi e via-se cada país de um colorido', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Língua Portuguesa', NULL, 'Q7 Item 2 (TPS 2018): Texto X | diferente, podia-se tomar isso ao pé da letra. É verdade que o mundo continuou a ser uma colcha de retalhos; mas são todos da mesma cor. Bombaim, Roma, Tóquio, que se escondiam, 7 cada um com seu peculiar mistério, nos compartimentos estanques da sua própria civilização, agora, a julgar pelos filmes, estão perfeitamente padronizados, universalizados. 10 E, no mundo de hoje, para desconsolo dos descendentes de Sindbad e de Marco Polo, a única cor local das cidades famosas são os turistas. Mário Quintana. Mapa-múndi. In: Prosa\&Verso. Porto Alegre: Globo, 1978, p. 60. Com relação aos aspectos linguísticos do texto X, julgue (C ou E) os itens a seguir. 1 Caso o pronome “esses” (R.1) fosse substituído por estes, seriam mantidas a correção gramatical do período e as principais informações veicu', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Língua Portuguesa', NULL, 'Q7 Item 3 (TPS 2018): Texto X | Até meados do século XIX, a classe que trafica adquire bens para convertê-los em lucro e benefício. Daí em diante, ela será outra. Um traço para distinguir as duas fases já', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Língua Portuguesa', NULL, 'Q7 Item 4 (TPS 2018): Texto X | foi lembrado: o despertar do entorpecimento que lhe causava a predominância social da classe proprietária, por sua vez, na cúpula, recoberta pelo estamento dos que mandam, governam 7 e dirigem a política. Mas que não haja equívoco: o arrastar na sombra denunciava-lhe prestígio negativo, oriundo da composição de estrangeiros entre seus membros e do tipo de 10 negócios a que se dedicava, sobretudo no comércio negreiro. Não que vivesse alheia à importância econômica ou à eficiência no trato do sistema. Era ela a categoria dinâmica da 13 economia, a que lhe dava impulso à energia, financiando a produção, com o fornecimento de crédito e escravos. Sobretudo, armava o elo que ligava o café ao comércio 16 mundial, polo diretor, em última instância, da economia nacional, dependente de flutuação de ', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q8 Item 1 (TPS 2018): Considerando as ideias e os aspectos linguísticos do texto XI, julgue (C ou E) os itens a seguir. | De acordo com o texto, além do exercício da direção do poder político, à classe proprietária cabia dinamizar a economia, relegando à sombra a classe sustentada pelo tráfico.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q8 Item 2 (TPS 2018): Considerando as ideias e os aspectos linguísticos do texto XI, julgue (C ou E) os itens a seguir. | Para o autor, Machado de Assis capta, em sua literatura, a decadência da classe empresarial, representando-lhe a “queda de escrúpulos, virtudes e valores” (R. 50 e 51).', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q8 Item 3 (TPS 2018): Considerando as ideias e os aspectos linguísticos do texto XI, julgue (C ou E) os itens a seguir. | Na frase “o arrastar na sombra denunciava-lhe prestígio negativo” (R. 7 e 8), a substituição do pronome oblíquo “lhe” por a ela prejudicaria a correção gramatical do texto.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q8 Item 4 (TPS 2018): Considerando as ideias e os aspectos linguísticos do texto XI, julgue (C ou E) os itens a seguir. | Os termos “categoria dinâmica” (R.12), “classe lucrativa” (R.33) e “O empresário” (R.42) são expressões usadas para construir referências relativas a um mesmo campo semântico.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q9 Item 1 (TPS 2018): Ainda considerando os sentidos e os aspectos linguísticos do texto XI, julgue (C ou E) os itens que se seguem. | No período “Sobe uma classe e dentro dela elevam-se muitos aspirantes a essa camada” (R. 36 a 38), os termos “uma classe” e “muitos aspirantes a essa camada” exercem função de sujeito nas orações em que se inserem.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q9 Item 2 (TPS 2018): Ainda considerando os sentidos e os aspectos linguísticos do texto XI, julgue (C ou E) os itens que se seguem. | A correção gramatical e os sentidos do texto seriam preservados caso o trecho “ligava-se ao estrato dirigente, o estamento, com repulsa” (R. 22 e 23) fosse reescrito da seguinte forma: relacionava-se com a camada que estava no poder, à corte, com aversão.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q9 Item 3 (TPS 2018): Ainda considerando os sentidos e os aspectos linguísticos do texto XI, julgue (C ou E) os itens que se seguem. | No trecho “toda uma camada quer os bens da vida” (R. 40 e 41), o artigo indefinido foi empregado como item de realce, razão por que sua eliminação não prejudicaria a correção gramatical nem o sentido original do texto.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q9 Item 4 (TPS 2018): Ainda considerando os sentidos e os aspectos linguísticos do texto XI, julgue (C ou E) os itens que se seguem. | Nas expressões “seu preconceito” (R.45) e “seu sarcasmo” (R. 45 e 46), o pronome possessivo remete a referentes distintos. Espaço livre CESPE | CEBRASPE – IRBr – Aplicação: 2018', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q10 Item 1 (TPS 2018): Texto XII | Impugnada a todo instante pela escravidão a ideologia liberal, que era a das jovens nações emancipadas da América, descarrilava. Seria fácil deduzir o sistema de seus', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q10 Item 2 (TPS 2018): Texto XII | contrassensos, todos verdadeiros, muitos dos quais agitaram a consciência teórica e moral de nosso século XIX. Já vimos uma coleção deles. No entanto, estas dificuldades 7 permaneciam curiosamente inessenciais. O teste da realidade não parecia importante. É como se coerência e generalidade não pesassem muito, ou como se a esfera da cultura ocupasse 10 uma posição alterada, cujos critérios fossem outros — mas outros em relação a quê? Por sua mera presença, a escravidão indicava a impropriedade das ideias liberais; o que, entretanto, 13 é menos que orientar-lhes o movimento. Sendo embora a relação produtiva fundamental, a escravidão não era o nexo efetivo da vida ideológica. A chave desta era diversa. Para 16 descrevê-la é preciso retomar o país como todo. Esquematizando, pode-se dizer que a', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Política Internacional', NULL, 'Q11 Item 1 (TPS 2018): Tendo em vista que a participação do Brasil na promoção de esforços de integração na América do Sul se dá sob diferentes formas e instâncias e envolve iniciativas político-diplomáticas e o engajamento em mecanismos regionais e sub-regionais de integração econômica e de cooperação, julgue (C ou E) os itens seguintes, relativos a esse tema. | A integração sul-americana despontou na agenda da política externa brasileira mediante iniciativas como a proposta de integração de natureza comercial formulada na primeira metade dos anos 90 do século passado e na década seguinte; a organização da Primeira Reunião de Presidentes de Países da América do Sul; a criação da Comunidade Sul-Americana de Nações (CASA); e a criação da União de Nações Sul-Americanas (UNASUL).', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Política Internacional', NULL, 'Q11 Item 2 (TPS 2018): Tendo em vista que a participação do Brasil na promoção de esforços de integração na América do Sul se dá sob diferentes formas e instâncias e envolve iniciativas político-diplomáticas e o engajamento em mecanismos regionais e sub-regionais de integração econômica e de cooperação, julgue (C ou E) os itens seguintes, relativos a esse tema. | A Iniciativa para a Integração da Infraestrutura Sul-Americana (IIRSA), criada por iniciativa brasileira, em 2000, segue como principal mecanismo para o tratamento de questões afetas à infraestrutura regional no Conselho Sul-Americano de Infraestrutura e Planejamento (COSIPLAN), da União de Nações Sul-Americanas (UNASUL).', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Política Internacional', NULL, 'Q11 Item 3 (TPS 2018): Tendo em vista que a participação do Brasil na promoção de esforços de integração na América do Sul se dá sob diferentes formas e instâncias e envolve iniciativas político-diplomáticas e o engajamento em mecanismos regionais e sub-regionais de integração econômica e de cooperação, julgue (C ou E) os itens seguintes, relativos a esse tema. | Concebido originalmente para o estabelecimento de um mercado comum, o Mercado Comum do Sul (MERCOSUL) incorporou à sua agenda e à sua estrutura organizacional, ainda no seu período de transição, um amplo conjunto de temas não afetos à integração econômica, o que dificultou sua consolidação como união aduaneira.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Política Internacional', NULL, 'Q11 Item 4 (TPS 2018): Tendo em vista que a participação do Brasil na promoção de esforços de integração na América do Sul se dá sob diferentes formas e instâncias e envolve iniciativas político-diplomáticas e o engajamento em mecanismos regionais e sub-regionais de integração econômica e de cooperação, julgue (C ou E) os itens seguintes, relativos a esse tema. | Embora o Conselho de Defesa Sul-Americano (CDS) tenha sido concebido para, entre outros objetivos, consolidar a América do Sul como zona de paz, temas centrais para a segurança regional, como a luta contra o narcotráfico e o enfrentamento da delinquência associada aos ilícitos transnacionais não se afirmaram em sua agenda, tendo sido assumidos em conselhos específicos da União de Nações Sul-Americanas (UNASUL).', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Política Internacional', NULL, 'Q12 Item 1 (TPS 2018): A crescente exposição do Estado e da sociedade brasileira às dinâmicas internacionais tem, como contrapartida, entre outras, a maior importância conferida às questões de segurança nos planos regional e global. A respeito desse assunto, julgue (C ou E) os itens a seguir. | A segurança se incorporou à agenda da política externa brasileira no século XXI, em decorrência do ativismo do país em espaços e iniciativas de caráter multilateral e de alcance global, constituindo exemplo dessas ações o maior engajamento em operações de paz e nos debates sobre segurança humana e intervenção humanitária e sobre a reforma do Conselho de Segurança das Nações Unidas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Política Internacional', NULL, 'Q12 Item 3 (TPS 2018): A crescente exposição do Estado e da sociedade brasileira às dinâmicas internacionais tem, como contrapartida, entre outras, a maior importância conferida às questões de segurança nos planos regional e global. A respeito desse assunto, julgue (C ou E) os itens a seguir. | Apesar da reconhecida centralidade das instâncias e instrumentos multilaterais de alcance global para o enfrentamento ao narcotráfico, o sistema interamericano propicia importantes espaços e instrumentos para a participação do Brasil nos esforços internacionais voltados para o compartilhamento de boas práticas e a realização de projetos voltados para aquele fim.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Política Internacional', NULL, 'Q12 Item 4 (TPS 2018): A crescente exposição do Estado e da sociedade brasileira às dinâmicas internacionais tem, como contrapartida, entre outras, a maior importância conferida às questões de segurança nos planos regional e global. A respeito desse assunto, julgue (C ou E) os itens a seguir. | A preocupação do Brasil em não se converter em palco ou alvo de ações terroristas fundamenta sua opção de, na cooperação internacional para o enfrentamento ao terrorismo internacional, privilegiar iniciativas de caráter preventivo, a cooperação jurídica e o intercâmbio de informações policiais e de inteligência por vias bilaterais, em detrimento daquelas conduzidas por meio de instâncias e instrumentos multilaterais.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Política Internacional', NULL, 'Q13 Item 1 (TPS 2018): Considerando que as relações com os países do continente americano representam importante vertente da política externa brasileira, e que elas envolvem um amplo espectro de interesses políticos, econômicos e de segurança, tratados bilateral e multilateralmente em condições diversas, conforme seu alcance e densidade, julgue (C ou E) os itens que se seguem. | Sob a ótica da política externa norte-americana, as relações com o Brasil, tradicionalmente diversificadas, estão, no presente, assentadas em interesses de natureza puramente econômico-comercial, haja vista as recorrentes dificuldades enfrentadas na construção de convergências e na cooperação sobre temas políticos e de segurança no plano global e importantes divergências quanto às respectivas prioridades no plano das relações hemisféricas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Política Internacional', NULL, 'Q13 Item 2 (TPS 2018): Considerando que as relações com os países do continente americano representam importante vertente da política externa brasileira, e que elas envolvem um amplo espectro de interesses políticos, econômicos e de segurança, tratados bilateral e multilateralmente em condições diversas, conforme seu alcance e densidade, julgue (C ou E) os itens que se seguem. | Recentemente, no âmbito da sua política externa, a maior aproximação do Brasil com os países da América Central teve amparo, inicialmente, em projetos de cooperação técnica e em iniciativas para a expansão do comércio e a promoção de investimentos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Política Internacional', NULL, 'Q13 Item 3 (TPS 2018): Considerando que as relações com os países do continente americano representam importante vertente da política externa brasileira, e que elas envolvem um amplo espectro de interesses políticos, econômicos e de segurança, tratados bilateral e multilateralmente em condições diversas, conforme seu alcance e densidade, julgue (C ou E) os itens que se seguem. | O esforço diplomático brasileiro empreendido a partir de 2009 com o propósito de impulsionar as relações com os países do Caribe não produziu resultados expressivos no campo comercial, tendo tanto as exportações quanto as importações brasileiras sofrido acentuado declínio nos últimos cinco anos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Política Internacional', NULL, 'Q13 Item 4 (TPS 2018): Considerando que as relações com os países do continente americano representam importante vertente da política externa brasileira, e que elas envolvem um amplo espectro de interesses políticos, econômicos e de segurança, tratados bilateral e multilateralmente em condições diversas, conforme seu alcance e densidade, julgue (C ou E) os itens que se seguem. | A participação do Brasil no sistema interamericano a partir do final da Guerra Fria se expressa de forma heterogênea no que se refere ao seu posicionamento diante de propostas e iniciativas emanadas desse sistema, como, por exemplo, o decidido apoio prestado ao fortalecimento da institucionalidade democrática no continente, a reticência frente à agenda de segurança hemisférica na última década do século passado e o posicionamento crítico adotado no início desta década em relação ao Sistema Interamericano de Direitos Humanos. CESPE | CEBRASPE – IRBr – Aplicação: 2018', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Política Internacional', NULL, 'Q14 Item 2 (TPS 2018): Além de ser, no presente, a região de maior dinamismo econômico global, a Ásia é um espaço que abriga importantes dinâmicas políticas e de segurança que repercutem para além da própria região. Por essa razão, países que, a exemplo do Brasil, procuram, na maior aproximação com os países asiáticos, oportunidades de aprofundar sua inserção internacional devem considerar tanto os principais vetores das políticas externas na região como os antecedentes de seu próprio relacionamento no plano bilateral | A China experimentou significativa inflexão em sua política externa ao valorizar o aprofundamento dos laços econômicos com os países em seu contexto regional por meio de mecanismos coletivos, o que se expressa no apoio a propostas e iniciativas como a Área de Livre Comércio da Ásia Pacífico, a Comunidade Econômica do Leste da Ásia e a Parceria Econômica Regional Abrangente.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Política Internacional', NULL, 'Q14 Item 3 (TPS 2018): Além de ser, no presente, a região de maior dinamismo econômico global, a Ásia é um espaço que abriga importantes dinâmicas políticas e de segurança que repercutem para além da própria região. Por essa razão, países que, a exemplo do Brasil, procuram, na maior aproximação com os países asiáticos, oportunidades de aprofundar sua inserção internacional devem considerar tanto os principais vetores das políticas externas na região como os antecedentes de seu próprio relacionamento no plano bilateral | A política externa da Índia possui como importantes vetores, em sua dimensão global, a promoção da governança, o acesso a recursos energéticos em bases estáveis, a promoção da segurança alimentar e, no plano regional, a cooperação com a China, no âmbito do BRICS, na construção de novas instituições econômicas e, bilateralmente, em iniciativas como a articulação da infraestrutura da Nova Rota da Seda.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Política Internacional', NULL, 'Q14 Item 4 (TPS 2018): Além de ser, no presente, a região de maior dinamismo econômico global, a Ásia é um espaço que abriga importantes dinâmicas políticas e de segurança que repercutem para além da própria região. Por essa razão, países que, a exemplo do Brasil, procuram, na maior aproximação com os países asiáticos, oportunidades de aprofundar sua inserção internacional devem considerar tanto os principais vetores das políticas externas na região como os antecedentes de seu próprio relacionamento no plano bilateral | A parceria estratégica entre China e Brasil tem servido de plataforma para a crescente diversificação do seu relacionamento bilateral, cuja agenda alcançou temas que ganharam relevância ao longo da última década. Tradicionalmente marcadas pela prevalência de interesses econômico-comerciais e pela cooperação aeroespacial, as relações entre esses países têm privilegiado iniciativas conjuntas em áreas como meio ambiente, saúde pública e tecnologias sensíveis.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Política Internacional', NULL, 'Q15 Item 1 (TPS 2018): Considerando que a inserção internacional do Brasil tem na atuação em foros multilaterais instrumento privilegiado para o tratamento dos principais temas da agenda global nas mais diferentes áreas, julgue (C ou E) os itens subsequentes, relativos a esse tema. | O estancamento da Rodada de Doha paralisou as negociações sobre temas comerciais no âmbito da Organização Mundial do Comércio, arrefecendo a implementação de decisões alcançadas nas últimas conferências ministeriais e a atividade do Órgão de Solução de Controvérsias. Em razão disso, fortalecem-se negociações bilaterais e regionais, incorporando disciplinas comerciais não alcançadas pela normativa multilateral, tendência da qual o Brasil está dissociado.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Política Internacional', NULL, 'Q15 Item 2 (TPS 2018): Considerando que a inserção internacional do Brasil tem na atuação em foros multilaterais instrumento privilegiado para o tratamento dos principais temas da agenda global nas mais diferentes áreas, julgue (C ou E) os itens subsequentes, relativos a esse tema. | A decisão dos Estados Unidos da América de abandonar o Acordo de Paris aumentou as incertezas sobre o efetivo cumprimento das metas assumidas pelos países que o ratificaram. Nesse contexto, o Brasil reiterou a disposição de trabalhar com os demais signatários para rever os compromissos assumidos, de modo a mitigar os impactos da retirada norte-americana e salvaguardar o objetivo de manter a temperatura média da Terra em, no máximo, 2 ºC acima dos níveis pré-industriais.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Política Internacional', NULL, 'Q15 Item 3 (TPS 2018): Considerando que a inserção internacional do Brasil tem na atuação em foros multilaterais instrumento privilegiado para o tratamento dos principais temas da agenda global nas mais diferentes áreas, julgue (C ou E) os itens subsequentes, relativos a esse tema. | A Conferência das Nações Unidas sobre Comércio e Desenvolvimento (UNCTAD) representa, no presente, importante espaço de apoio aos países em desenvolvimento no que diz respeito ao seguimento e à implementação dos Objetivos de Desenvolvimento Sustentável que conformam a Agenda 2030 para o desenvolvimento sustentável e, de modo particular, daqueles voltados para a dimensão econômica.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Política Internacional', NULL, 'Q15 Item 4 (TPS 2018): Considerando que a inserção internacional do Brasil tem na atuação em foros multilaterais instrumento privilegiado para o tratamento dos principais temas da agenda global nas mais diferentes áreas, julgue (C ou E) os itens subsequentes, relativos a esse tema. | A necessidade de aprimorar a governança global por meio de uma nova arquitetura financeira ocupa lugar de destaque na agenda do G-20, em que os países de economias emergentes procuram exercer maior protagonismo e influência nas tratativas sobre o tema. Exemplifica tal influência a expectativa do grupo de que as negociações sobre a reforma do sistema de quotas do Fundo Monetário Internacional, ora em curso, resulte em maior peso das economias emergentes e dos países em desenvolvimento em geral naquele organismo, pleito também defendido pelo Brasil.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q16 Item 1 (TPS 2018): Tendo em vista que a Europa é referente histórico no repertório das relações internacionais do Brasil e se mantém como importante parceira desse país tanto por meio de países individualmente, em eixos bilaterais, como por meio das instituições comunitárias, julgue (C ou E) os itens seguintes, acerca das relações do Brasil com países europeus e organismos internacionais. | As relações da França e do Reino Unido com o Brasil são conduzidas no âmbito das respectivas parcerias estratégicas, cujas agendas se concentram em temas econômicos, no caso da França, e, no caso do Reino Unido, em iniciativas voltadas para a cooperação setorial em áreas como agricultura familiar, ciência e tecnologia, defesa e energia nuclear.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q16 Item 2 (TPS 2018): Tendo em vista que a Europa é referente histórico no repertório das relações internacionais do Brasil e se mantém como importante parceira desse país tanto por meio de países individualmente, em eixos bilaterais, como por meio das instituições comunitárias, julgue (C ou E) os itens seguintes, acerca das relações do Brasil com países europeus e organismos internacionais. | Os diálogos setoriais são o principal instrumento do intercâmbio de informações e experiências para o planejamento, o acompanhamento e a avaliação de inciativas nas relações entre a União Europeia e o Brasil; a centralidade reflete a amplitude e a forte segmentação das relações bilaterais e a inexistência de uma moldura política de direcionamento estratégico para tais relações.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q16 Item 3 (TPS 2018): Tendo em vista que a Europa é referente histórico no repertório das relações internacionais do Brasil e se mantém como importante parceira desse país tanto por meio de países individualmente, em eixos bilaterais, como por meio das instituições comunitárias, julgue (C ou E) os itens seguintes, acerca das relações do Brasil com países europeus e organismos internacionais. | A parceria estratégica entre a Rússia e o Brasil firmada em 2002 ensejou, ao longo da década, significativo incremento do comércio bilateral, avanço limitado na cooperação em setores como defesa e atividades aeroespaciais e forte impulso na concertação de posições em fóruns internacionais como o BRICS e o G-20.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q16 Item 4 (TPS 2018): Tendo em vista que a Europa é referente histórico no repertório das relações internacionais do Brasil e se mantém como importante parceira desse país tanto por meio de países individualmente, em eixos bilaterais, como por meio das instituições comunitárias, julgue (C ou E) os itens seguintes, acerca das relações do Brasil com países europeus e organismos internacionais. | A proteção e o uso sustentável das florestas tropicais e a promoção das energias renováveis e da eficiência energética são temas prioritários na agenda da cooperação teuto-brasileira. A prioridade desses temas reflete a complementariedade advinda da importância do Brasil nos esforços de mitigação dos efeitos da mudança climática e para a conservação da biodiversidade no planeta, e do domínio, por parte da Alemanha, de tecnologias ambientais e energéticas de grande relevância para o desenvolvimento sustentável. CESPE | CEBRASPE – IRBr – Aplicação: 2018', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q17 Item 1 (TPS 2018): Segundo o Tratado de Lisboa, a União Europeia (UE) tem como valores o respeito pela dignidade humana, a liberdade, a democracia, a igualdade, o estado de direito e o respeito pelos direitos humanos e como objetivo a promoção da paz, dos valores comuns e do bem-estar dos seus povos. No que concerne ao tema da integração europeia, julgue (C ou E) os itens seguintes. | A aproximação entre o MERCOSUL e a UE remonta à assinatura do Acordo-Quadro de Cooperação Inter-regional em 1995, mas, desde então, as negociações com vistas a um acordo de livre comércio não avançaram.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q17 Item 2 (TPS 2018): Segundo o Tratado de Lisboa, a União Europeia (UE) tem como valores o respeito pela dignidade humana, a liberdade, a democracia, a igualdade, o estado de direito e o respeito pelos direitos humanos e como objetivo a promoção da paz, dos valores comuns e do bem-estar dos seus povos. No que concerne ao tema da integração europeia, julgue (C ou E) os itens seguintes. | São países candidatos a adesão à UE: Albânia, Macedônia, Montenegro, Sérvia e Turquia.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q17 Item 3 (TPS 2018): Segundo o Tratado de Lisboa, a União Europeia (UE) tem como valores o respeito pela dignidade humana, a liberdade, a democracia, a igualdade, o estado de direito e o respeito pelos direitos humanos e como objetivo a promoção da paz, dos valores comuns e do bem-estar dos seus povos. No que concerne ao tema da integração europeia, julgue (C ou E) os itens seguintes. | Composta por um representante de cada um dos Estados-membros da UE, a Comissão Europeia é o órgão executivo da UE e defende seus interesses gerais.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q17 Item 4 (TPS 2018): Segundo o Tratado de Lisboa, a União Europeia (UE) tem como valores o respeito pela dignidade humana, a liberdade, a democracia, a igualdade, o estado de direito e o respeito pelos direitos humanos e como objetivo a promoção da paz, dos valores comuns e do bem-estar dos seus povos. No que concerne ao tema da integração europeia, julgue (C ou E) os itens seguintes. | A despeito de seus nomes, o Conselho da Europa e a Corte Europeia de Direitos Humanos não são instituições da UE.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q18 Item 1 (TPS 2018): No discurso de abertura do Debate Geral da 66.ª Assembleia-Geral da Organização das Nações Unidas (ONU), a presidenta Dilma Rousseff afirmou: “apenas uma Palestina livre e soberana poderá atender aos legítimos anseios de Israel por paz com seus vizinhos, segurança em suas fronteiras e estabilidade política em seu entorno regional”. Tendo esse fragmento de texto como referência inicial, julgue (C ou E) os próximos itens, a respeito da questão árabe-israelense. | O Brasil reconheceu o Estado da Palestina nas fronteiras de 1967 e foi seguido por vários países sul-americanos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q18 Item 2 (TPS 2018): No discurso de abertura do Debate Geral da 66.ª Assembleia-Geral da Organização das Nações Unidas (ONU), a presidenta Dilma Rousseff afirmou: “apenas uma Palestina livre e soberana poderá atender aos legítimos anseios de Israel por paz com seus vizinhos, segurança em suas fronteiras e estabilidade política em seu entorno regional”. Tendo esse fragmento de texto como referência inicial, julgue (C ou E) os próximos itens, a respeito da questão árabe-israelense. | Os Acordos de Oslo criaram uma Autoridade Palestina, mas não alteraram o status de Jerusalém.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q18 Item 3 (TPS 2018): No discurso de abertura do Debate Geral da 66.ª Assembleia-Geral da Organização das Nações Unidas (ONU), a presidenta Dilma Rousseff afirmou: “apenas uma Palestina livre e soberana poderá atender aos legítimos anseios de Israel por paz com seus vizinhos, segurança em suas fronteiras e estabilidade política em seu entorno regional”. Tendo esse fragmento de texto como referência inicial, julgue (C ou E) os próximos itens, a respeito da questão árabe-israelense. | Após o presidente dos Estados Unidos da América, Donald Trump, anunciar a mudança da embaixada norte-americana para Jerusalém, a Assembleia-Geral da ONU aprovou uma resolução segundo a qual “quaisquer decisões e ações que pretendam alterar o caráter, o status ou a composição demográfica da Cidade Santa de Jerusalém não têm efeito legal”.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q18 Item 4 (TPS 2018): No discurso de abertura do Debate Geral da 66.ª Assembleia-Geral da Organização das Nações Unidas (ONU), a presidenta Dilma Rousseff afirmou: “apenas uma Palestina livre e soberana poderá atender aos legítimos anseios de Israel por paz com seus vizinhos, segurança em suas fronteiras e estabilidade política em seu entorno regional”. Tendo esse fragmento de texto como referência inicial, julgue (C ou E) os próximos itens, a respeito da questão árabe-israelense. | O brasileiro Osvaldo Aranha foi o presidente da Assembleia-Geral da ONU em 1947, que aprovou a resolução sobre o Plano de Partição da Palestina, com a chamada “solução de dois Estados”.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q19 Item 1 (TPS 2018): A respeito das mudanças na atual política externa dos Estados Unidos da América (EUA), julgue (C ou E) os itens a seguir. | Não é a primeira vez que um presidente dos EUA pede a seus aliados europeus para incrementar seus investimentos em defesa. Entretanto, Donald Trump tem pressionado com frequência os líderes europeus por não aumentarem sua contribuição ao orçamento da Organização do Tratado do Atlântico Norte (OTAN).', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q19 Item 2 (TPS 2018): A respeito das mudanças na atual política externa dos Estados Unidos da América (EUA), julgue (C ou E) os itens a seguir. | Depois de ameaças recíprocas que se prolongaram por vários meses, Donald Trump e Kim Jong-un encontraram-se em Singapura, em 2018, e assinaram uma declaração conjunta em que os EUA e a Coreia do Norte se comprometem a trabalhar em favor da paz e da prosperidade mundial. A Coreia do Norte prometeu que aderirá ao Tratado de Não-Proliferação de Armas Nucleares (TNP).', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q19 Item 3 (TPS 2018): A respeito das mudanças na atual política externa dos Estados Unidos da América (EUA), julgue (C ou E) os itens a seguir. | O governo saudita lidera uma coalizão militar que tem combatido o grupo aliado do Irã que luta para manter-se no poder no Iêmen desde 2015. Donald Trump obteve a aprovação do Congresso norte-americano para prestar ampla ajuda militar aos sauditas na luta pelo controle do Iêmen, o que inclui o envio de centenas de soldados e de aviões armados com mísseis equipados com ogivas nucleares.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q19 Item 4 (TPS 2018): A respeito das mudanças na atual política externa dos Estados Unidos da América (EUA), julgue (C ou E) os itens a seguir. | Os governos da França, da Alemanha e do Reino Unido não conseguiram dissuadir Washington de deixar o acordo nuclear firmado pelo grupo chamado de P5+1, ou seja, os cinco membros permanentes do Conselho de Segurança da ONU e a Alemanha, e o Irã, em 2015. A reação imediata do Irã foi proibir a exportação de petróleo e gás iranianos aos EUA. Espaço livre CESPE | CEBRASPE – IRBr – Aplicação: 2018', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q20 Item 1 (TPS 2018): As teorias das relações internacionais têm a finalidade de formular métodos e conceitos que permitam compreender a natureza e o funcionamento do sistema internacional, bem como explicar os fenômenos mais importantes que moldam a política mundial. J. P. Nogueira e N. Messari. Teoria das relações internacionais: correntes e debates. Rio de Janeiro: Elsevier, 2005, p. 2. A respeito do assunto abordado no fragmento de texto precedente, julgue (C ou E) os próximos itens. | Embora o realismo seja uma tradição teórica da área de Relações Internacionais que apresenta uma grande diversidade, é possível afirmar que, para os realistas, os Estados são os atores centrais das relações internacionais, as quais se caracterizam pela anarquia e, sobretudo, pela cooperação para sobreviver.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q20 Item 2 (TPS 2018): As teorias das relações internacionais têm a finalidade de formular métodos e conceitos que permitam compreender a natureza e o funcionamento do sistema internacional, bem como explicar os fenômenos mais importantes que moldam a política mundial. J. P. Nogueira e N. Messari. Teoria das relações internacionais: correntes e debates. Rio de Janeiro: Elsevier, 2005, p. 2. A respeito do assunto abordado no fragmento de texto precedente, julgue (C ou E) os próximos itens. | As análises pós-coloniais, que representam uma contribuição relativamente recente na área de Relações Internacionais, questionam as concepções modernizadoras ocidentais e a politização dos conflitos delas resultantes.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q20 Item 3 (TPS 2018): As teorias das relações internacionais têm a finalidade de formular métodos e conceitos que permitam compreender a natureza e o funcionamento do sistema internacional, bem como explicar os fenômenos mais importantes que moldam a política mundial. J. P. Nogueira e N. Messari. Teoria das relações internacionais: correntes e debates. Rio de Janeiro: Elsevier, 2005, p. 2. A respeito do assunto abordado no fragmento de texto precedente, julgue (C ou E) os próximos itens. | Muitos realistas e liberais atribuem antecedência ontológica aos agentes ou à estrutura nas relações internacionais. Os construtivistas afirmam que o mundo é socialmente construído e negam, portanto, a antecedência ontológica dos agentes ou da estrutura.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q20 Item 4 (TPS 2018): As teorias das relações internacionais têm a finalidade de formular métodos e conceitos que permitam compreender a natureza e o funcionamento do sistema internacional, bem como explicar os fenômenos mais importantes que moldam a política mundial. J. P. Nogueira e N. Messari. Teoria das relações internacionais: correntes e debates. Rio de Janeiro: Elsevier, 2005, p. 2. A respeito do assunto abordado no fragmento de texto precedente, julgue (C ou E) os próximos itens. | A crença no progresso da humanidade e na sua racionalidade e a ideia de que a intensificação do comércio favorece a paz são alguns dos fundamentos do liberalismo. É na tradição liberal que se encontram os fundamentos para a criação das organizações internacionais pelas potências vencedoras da Segunda Guerra Mundial.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q21 Item 1 (TPS 2018): A respeito do tema refugiados, apátridas e migrantes, julgue (C ou E) os itens a seguir. | Em 2017, o número de pessoas que foram forçadas a se deslocar em razão de conflitos em países como a Síria retrocedeu, apesar do crescimento observado nos anos anteriores.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q21 Item 2 (TPS 2018): A respeito do tema refugiados, apátridas e migrantes, julgue (C ou E) os itens a seguir. | O texto do Pacto Global sobre Migração Segura, Ordenada e Regular foi aprovado em 2018 e sua natureza jurídica será a de um instrumento internacional não vinculante.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q21 Item 3 (TPS 2018): A respeito do tema refugiados, apátridas e migrantes, julgue (C ou E) os itens a seguir. | O Brasil é parte da Convenção sobre o Estatuto dos Apátridas de 1954 e da Convenção para a Redução dos Casos de Apatridia de 1961, tendo reconhecido pela primeira vez, em 2018, duas pessoas como apátridas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q21 Item 4 (TPS 2018): A respeito do tema refugiados, apátridas e migrantes, julgue (C ou E) os itens a seguir. | Devido à inter-relação entre as condições de refugiado e de migrante econômico, as pessoas que cruzam a fronteira de seu país em busca de melhor padrão de vida também estão sob a proteção da Convenção relativa ao Estatuto dos Refugiados.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q22 Item 1 (TPS 2018): As operações de paz sempre tiveram importância no âmbito da atuação da ONU e, a partir do fim da Guerra Fria, seu número cresceu significativamente. O Brasil participou de várias operações de paz da ONU, sendo essa participação coerente com a importância que historicamente a política externa brasileira tem atribuído às instâncias multilaterais, notadamente no campo da paz e da segurança internacionais. A esse respeito, julgue (C ou E) os itens seguintes. | A primeira operação de manutenção da paz foi criada pela ONU em 1956 para monitorar o cessar-fogo entre Egito e Israel na Crise do Suez. O Brasil participou dessa operação de paz, que se restringiu ao componente militar.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q22 Item 2 (TPS 2018): As operações de paz sempre tiveram importância no âmbito da atuação da ONU e, a partir do fim da Guerra Fria, seu número cresceu significativamente. O Brasil participou de várias operações de paz da ONU, sendo essa participação coerente com a importância que historicamente a política externa brasileira tem atribuído às instâncias multilaterais, notadamente no campo da paz e da segurança internacionais. A esse respeito, julgue (C ou E) os itens seguintes. | A Missão das Nações Unidas de Estabilização no Haiti (MINUSTAH) encerrou-se em 2017 e sua composição contou com uma notável maioria de países latino-americanos. O Brasil dividiu o comando do componente militar da missão com a Argentina e o Chile.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q22 Item 3 (TPS 2018): As operações de paz sempre tiveram importância no âmbito da atuação da ONU e, a partir do fim da Guerra Fria, seu número cresceu significativamente. O Brasil participou de várias operações de paz da ONU, sendo essa participação coerente com a importância que historicamente a política externa brasileira tem atribuído às instâncias multilaterais, notadamente no campo da paz e da segurança internacionais. A esse respeito, julgue (C ou E) os itens seguintes. | O Brasil participa da Força Interina das Nações Unidas no Líbano (UNIFIL). A Marinha do Brasil comanda a força-tarefa marítima que atua na costa libanesa.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q22 Item 4 (TPS 2018): As operações de paz sempre tiveram importância no âmbito da atuação da ONU e, a partir do fim da Guerra Fria, seu número cresceu significativamente. O Brasil participou de várias operações de paz da ONU, sendo essa participação coerente com a importância que historicamente a política externa brasileira tem atribuído às instâncias multilaterais, notadamente no campo da paz e da segurança internacionais. A esse respeito, julgue (C ou E) os itens seguintes. | No final da década de 80 e na década de 90 do século passado, operações de paz realizadas em Angola e Moçambique objetivaram monitorar a implementação de acordos de paz que buscaram colocar fim a guerras civis nesses dois grandes países africanos. O Brasil participou dessas operações de paz multidimensionais, ou seja, que não se restringiram a tarefas tipicamente militares. Espaço livre CESPE | CEBRASPE – IRBr – Aplicação: 2018 GEOGRAFIA', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Geografia', NULL, 'Q24 Item 1 (TPS 2018): A tabela seguinte mostra as taxas de desemprego em zonas urbanas em cada ano indicado, com relação à respectiva população total, na América Latina (AL), na Argentina (AG), no Brasil (BR), no Chile (CH), na Colômbia (CO), na Costa Rica (CR), no Equador (EQ), no México (MX), no Paraguai (PG), no Peru (PE) e no Uruguai (UG). Os dados de 2016 referem-se aos cinco primeiros meses desse ano. 1990 1994 1997 1999 2002 2005 2008 2010 2011 2012 2016 AL 5,6 7,2 8,4 10,6 10,4 9,4 7,5 8,3 ... 6,6 ... B ... . | O chamado Consenso de Washington preconizava três ideias principais: a abertura comercial dos países, diminuindo o protecionismo e possibilitando investimentos estrangeiros, a aplicação da economia de mercado e o controle fiscal macroeconômico. Em relação ao mercado de trabalho, o Consenso de Washington defendia a desregulamentação das leis trabalhistas, com impacto direto na geração de empregos formais.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Geografia', NULL, 'Q24 Item 2 (TPS 2018): A tabela seguinte mostra as taxas de desemprego em zonas urbanas em cada ano indicado, com relação à respectiva população total, na América Latina (AL), na Argentina (AG), no Brasil (BR), no Chile (CH), na Colômbia (CO), na Costa Rica (CR), no Equador (EQ), no México (MX), no Paraguai (PG), no Peru (PE) e no Uruguai (UG). Os dados de 2016 referem-se aos cinco primeiros meses desse ano. 1990 1994 1997 1999 2002 2005 2008 2010 2011 2012 2016 AL 5,6 7,2 8,4 10,6 10,4 9,4 7,5 8,3 ... 6,6 ... B ... . | Apesar da tendência de redução da taxa de desemprego após 2002 e para a maioria dos países referenciados, a crise econômica mundial e as crises de poder local forçaram o aumento do desemprego em 2016, no Brasil, na Costa Rica, no Equador, Peru e Uruguai, estimulando o setor quaternário da economia urbana desses países.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Geografia', NULL, 'Q24 Item 3 (TPS 2018): A tabela seguinte mostra as taxas de desemprego em zonas urbanas em cada ano indicado, com relação à respectiva população total, na América Latina (AL), na Argentina (AG), no Brasil (BR), no Chile (CH), na Colômbia (CO), na Costa Rica (CR), no Equador (EQ), no México (MX), no Paraguai (PG), no Peru (PE) e no Uruguai (UG). Os dados de 2016 referem-se aos cinco primeiros meses desse ano. 1990 1994 1997 1999 2002 2005 2008 2010 2011 2012 2016 AL 5,6 7,2 8,4 10,6 10,4 9,4 7,5 8,3 ... 6,6 ... B ... . | A Colômbia, na década de 90 do século passado, viveu uma relação inversamente proporcional entre a taxa de desemprego e a violência urbana, que foi catalisada pelo abandono de atividades rurais ante a atuação das FARC no país.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Geografia', NULL, 'Q24 Item 4 (TPS 2018): A tabela seguinte mostra as taxas de desemprego em zonas urbanas em cada ano indicado, com relação à respectiva população total, na América Latina (AL), na Argentina (AG), no Brasil (BR), no Chile (CH), na Colômbia (CO), na Costa Rica (CR), no Equador (EQ), no México (MX), no Paraguai (PG), no Peru (PE) e no Uruguai (UG). Os dados de 2016 referem-se aos cinco primeiros meses desse ano. 1990 1994 1997 1999 2002 2005 2008 2010 2011 2012 2016 AL 5,6 7,2 8,4 10,6 10,4 9,4 7,5 8,3 ... 6,6 ... B ... . | Na primeira década do presente século, o Uruguai, que apresentou considerável diminuição da taxa de desemprego urbano, implementou políticas sociais redistribucionistas e abriu-se para o debate sobre direitos políticos populares. B 66,3 ... ... 70,3 66,6 66,7 64,2 ... 63,7 62,7 63,1 M 26,3 ... ... 23,7 25,6 25,4 27,0 ... 26,6 27,6 27,5 A 7,4 ... ... 4,0 7,5 7,7 8,6 ... 9,5 9,6 9,3 MX B ... 68,4 ... ... 69,9 69,9 70,2 62,8 ... 64,4 ... M ... 29,3 ... ... 29,4 29,3 28,9 2', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q25 Item 1 (TPS 2018): Acerca dos diferentes tratamentos do conceito de território na geografia, julgue (C ou E) os itens a seguir. | Questões de consciência e de representação do espaço foram elaboradas e assimiladas, ao largo dos séculos XIX e XX, para a definição concreta e imaginária do território como fundamento de soberania do Estado nação.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q25 Item 2 (TPS 2018): Acerca dos diferentes tratamentos do conceito de território na geografia, julgue (C ou E) os itens a seguir. | A integração contemporânea de técnica, ciência e informação desabilitam a abordagem geográfica do território sob aspectos subjetivos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q25 Item 3 (TPS 2018): Acerca dos diferentes tratamentos do conceito de território na geografia, julgue (C ou E) os itens a seguir. | Territorialização, desterritorialização e reterritorialização constituem processos reveladores do movimento social e da dinâmica do capital, os quais geram e redefinem identidades e vínculos com o território.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q25 Item 4 (TPS 2018): Acerca dos diferentes tratamentos do conceito de território na geografia, julgue (C ou E) os itens a seguir. | O conceito de território abrange processos e relações restritos à economia e à política, de forma que as dimensões sociais da cultura direcionam-se às abordagens conceituais geográficas da paisagem e do lugar.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q26 Item 1 (TPS 2018): Os campos de petróleo da Rússia estão localizados no Vale do Volga, no sul dos Urais e, acima de tudo, na Sibéria, particularmente perto do oceano Ártico. Os grandes depósitos ao redor do mar Cáspio são agora dependentes de Estados que se tornaram independentes com o fim da União das Repúblicas Socialistas Soviéticas (Azerbaijão, Cazaquistão). Como o segundo maior produtor mundial de petróleo e o primeiro produtor de gás natural, a Rússia tem apostado grande parte de seu desenvolvimento econômic | A política russa de exportação de petróleo e gás natural é um fator geopolítico de poder no cenário mundial e o país compartilha da política norte-americana e da Organização dos Países Produtores e Exportadores de Petróleo — do qual é membro participante —, contrária ao acordo do clima de Paris.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q26 Item 2 (TPS 2018): Os campos de petróleo da Rússia estão localizados no Vale do Volga, no sul dos Urais e, acima de tudo, na Sibéria, particularmente perto do oceano Ártico. Os grandes depósitos ao redor do mar Cáspio são agora dependentes de Estados que se tornaram independentes com o fim da União das Repúblicas Socialistas Soviéticas (Azerbaijão, Cazaquistão). Como o segundo maior produtor mundial de petróleo e o primeiro produtor de gás natural, a Rússia tem apostado grande parte de seu desenvolvimento econômic | A Sibéria, porção asiática do território russo, é rica em recursos minerais, com destaques para petróleo, gás natural, carvão mineral e minério de ferro, e sua localização geográfica em relação à China e ao Japão, grandes consumidores de minérios, é estratégica para a economia russa.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q26 Item 3 (TPS 2018): Os campos de petróleo da Rússia estão localizados no Vale do Volga, no sul dos Urais e, acima de tudo, na Sibéria, particularmente perto do oceano Ártico. Os grandes depósitos ao redor do mar Cáspio são agora dependentes de Estados que se tornaram independentes com o fim da União das Repúblicas Socialistas Soviéticas (Azerbaijão, Cazaquistão). Como o segundo maior produtor mundial de petróleo e o primeiro produtor de gás natural, a Rússia tem apostado grande parte de seu desenvolvimento econômic | As gigantescas reservas de petróleo e gás natural em poder da Rússia sustentam a economia desse país, bem como a expansão de sua influência geopolítica para outras regiões do mundo, como o Oriente Médio e a Europa.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q26 Item 4 (TPS 2018): Os campos de petróleo da Rússia estão localizados no Vale do Volga, no sul dos Urais e, acima de tudo, na Sibéria, particularmente perto do oceano Ártico. Os grandes depósitos ao redor do mar Cáspio são agora dependentes de Estados que se tornaram independentes com o fim da União das Repúblicas Socialistas Soviéticas (Azerbaijão, Cazaquistão). Como o segundo maior produtor mundial de petróleo e o primeiro produtor de gás natural, a Rússia tem apostado grande parte de seu desenvolvimento econômic | A anexação da península da Criméia, no mar Negro, é fator de conflito entre Rússia, Ucrânia e demais países do Cáucaso. O conflito entre os países provocou o êxodo da população da Criméia, em grande parte ucraniana e muçulmana, para outros países, como Geórgia, Armênia e Cazaquistão, de maioria muçulmana e forte sentimento contra a Rússia.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q27 Item 1 (TPS 2018): No último meio século, houve uma mudança revolucionária em escala planetária: cada vez mais, as lojas locais dão lugar ao domínio dos gigantes da distribuição, como o Walmart e o Carrefour. Na Espanha, mais de 80% das compras das famílias são feitas em hipermercados e, dessas compras, 75% estão concentradas nas cinco maiores redes: Mercadona, Eroski, Carrefour, Auchan e Dia. Tal mudança está longe de ser uma realidade particular de um país ou de um setor: trata-se de uma tendência mundial.N. Cas | Os processos de produção de commodities como frutas tropicais, café, grãos e carnes são cada vez mais regulados pelas regras do mercado global. A apropriação de processos produtivos por corporações transnacionais associadas ao capital industrial e financeiro compõe novas redes de produção e consumo, articulando campo e cidade e determinando o que se produz e o que se consome.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q27 Item 2 (TPS 2018): No último meio século, houve uma mudança revolucionária em escala planetária: cada vez mais, as lojas locais dão lugar ao domínio dos gigantes da distribuição, como o Walmart e o Carrefour. Na Espanha, mais de 80% das compras das famílias são feitas em hipermercados e, dessas compras, 75% estão concentradas nas cinco maiores redes: Mercadona, Eroski, Carrefour, Auchan e Dia. Tal mudança está longe de ser uma realidade particular de um país ou de um setor: trata-se de uma tendência mundial.N. Cas | As cidades médias brasileiras são polos atrativos, tanto para fluxos migratórios internos, como para investimentos empresariais globalizados. Hipermercados, centros comerciais, lojas de franquia, concessionárias de veículos, hotéis e diversos serviços são instalados nessas cidades em diferentes regiões do país, caracterizando o processo de globalização do território brasileiro.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q27 Item 3 (TPS 2018): No último meio século, houve uma mudança revolucionária em escala planetária: cada vez mais, as lojas locais dão lugar ao domínio dos gigantes da distribuição, como o Walmart e o Carrefour. Na Espanha, mais de 80% das compras das famílias são feitas em hipermercados e, dessas compras, 75% estão concentradas nas cinco maiores redes: Mercadona, Eroski, Carrefour, Auchan e Dia. Tal mudança está longe de ser uma realidade particular de um país ou de um setor: trata-se de uma tendência mundial.N. Cas | O sistema político-econômico hegemônico atual é caracterizado pela existência de diferentes tipos de redes geográficas que dinamizam os sistemas produtivos e de consumo e redefinem em escala global os usos dos territórios. O mundo atual é homogeneizado pelas relações de consumo e produção que articulam todo o planeta.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q27 Item 4 (TPS 2018): No último meio século, houve uma mudança revolucionária em escala planetária: cada vez mais, as lojas locais dão lugar ao domínio dos gigantes da distribuição, como o Walmart e o Carrefour. Na Espanha, mais de 80% das compras das famílias são feitas em hipermercados e, dessas compras, 75% estão concentradas nas cinco maiores redes: Mercadona, Eroski, Carrefour, Auchan e Dia. Tal mudança está longe de ser uma realidade particular de um país ou de um setor: trata-se de uma tendência mundial.N. Cas | O processo desigual de produção de um mundo articulado e fluido é realizado por agentes econômicos e políticos que se utilizam de acordos comerciais e da formação de blocos geoeconômicos para a constituição de redes que transferem mercadorias, bens e serviços entre diversas regiões do planeta. A estratégia dos agentes econômicos no período da globalização pressupõe a mobilidade, entre outros fatores políticos e econômicos de integração produtiva. CESPE | CEBRASPE – IRBr', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q28 Item 1 (TPS 2018): O domínio da teoria absoluta do Estado e o abandono das dimensões relativas e relacionais a um papel subordinado foram particularmente assegurados na Europa Ocidental. Posteriormente, os processos de colonização estenderam à maior parte do planeta essa modalidade de territorialização. Evidentemente, nada de natural nessa forma concreta de territorialização, nem o recurso das teorias absolutas do espaço e tempo para consolidá-las: estamos diante de construções sociais e criações políticas. David  | O conhecimento do território, a construção simbólica do Estado Nação, a definição e segurança das fronteiras nacionais e internacionais são elementos geográficos que mantêm os Estados nacionais europeus articulados e integrados territorialmente no mundo atual.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q28 Item 2 (TPS 2018): O domínio da teoria absoluta do Estado e o abandono das dimensões relativas e relacionais a um papel subordinado foram particularmente assegurados na Europa Ocidental. Posteriormente, os processos de colonização estenderam à maior parte do planeta essa modalidade de territorialização. Evidentemente, nada de natural nessa forma concreta de territorialização, nem o recurso das teorias absolutas do espaço e tempo para consolidá-las: estamos diante de construções sociais e criações políticas. David  | A fragilização das potências europeias com a Segunda Guerra Mundial teve como consequências a independência das antigas colônias e a criação de novos Estados nacionais no continente africano.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q28 Item 3 (TPS 2018): O domínio da teoria absoluta do Estado e o abandono das dimensões relativas e relacionais a um papel subordinado foram particularmente assegurados na Europa Ocidental. Posteriormente, os processos de colonização estenderam à maior parte do planeta essa modalidade de territorialização. Evidentemente, nada de natural nessa forma concreta de territorialização, nem o recurso das teorias absolutas do espaço e tempo para consolidá-las: estamos diante de construções sociais e criações políticas. David  | A expansão ultramarina europeia influenciou a formação da sociedade e dos Estados nacionais colonizados e posteriormente independentes. No Brasil, por meio de construções simbólicas e políticas, a influência cultural europeia produziu um território nacional único, integrado e predominantemente europeu.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Economia', NULL, 'Q28 Item 4 (TPS 2018): O domínio da teoria absoluta do Estado e o abandono das dimensões relativas e relacionais a um papel subordinado foram particularmente assegurados na Europa Ocidental. Posteriormente, os processos de colonização estenderam à maior parte do planeta essa modalidade de territorialização. Evidentemente, nada de natural nessa forma concreta de territorialização, nem o recurso das teorias absolutas do espaço e tempo para consolidá-las: estamos diante de construções sociais e criações políticas. David  | A descrição e o conhecimento geográfico feitos pelos viajantes e cronistas europeus durante a colonização, bem como a sua cartografia e representações, serviram às potências europeias para o domínio do novo mundo, de seus territórios e povos, para a delimitação de fronteiras e a exploração de seus recursos. NOÇÕES DE DIREITO E DIREITO INTERNACIONAL PÚBLICO', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Direito Internacional Público', NULL, 'Q29 Item 1 (TPS 2018): Com relação à classificação da Constituição, à competência dos entes federativos, ao ato jurídico e à personalidade jurídica, julgue (C ou E) os itens que se seguem. | A vigente Constituição brasileira é, no que se refere à estabilidade, semirrígida, pois, além de conter normas modificáveis por processo legislativo dificultoso e solene, possui também normas flexíveis, que podem ser alteradas por processo legislativo ordinário.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Direito Internacional Público', NULL, 'Q29 Item 2 (TPS 2018): Com relação à classificação da Constituição, à competência dos entes federativos, ao ato jurídico e à personalidade jurídica, julgue (C ou E) os itens que se seguem. | Compete à União, aos estados e ao Distrito Federal legislar concorrentemente sobre cidadania e naturalização, limitando-se a União a estabelecer normas gerais e os demais entes a legislar em caráter suplementar.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Direito Internacional Público', NULL, 'Q29 Item 3 (TPS 2018): Com relação à classificação da Constituição, à competência dos entes federativos, ao ato jurídico e à personalidade jurídica, julgue (C ou E) os itens que se seguem. | O ato jurídico em sentido estrito é ato voluntário que produz os efeitos já previamente estabelecidos pela norma jurídica, como, por exemplo, quando alguém transfere a residência com a intenção de se mudar, decorrendo da lei a consequente mudança do domicílio.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2018, 'Direito Internacional Público', NULL, 'Q29 Item 4 (TPS 2018): Com relação à classificação da Constituição, à competência dos entes federativos, ao ato jurídico e à personalidade jurídica, julgue (C ou E) os itens que se seguem. | Considera-se personalidade jurídica a capacidade in abstracto de ser sujeito de direitos ou obrigações, ou seja, de exercer determinadas atividades e de cumprir determinados deveres decorrentes da convivência em sociedade.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
